describe("doctests of sympy.assumptions.refine", () => {
  // the arguments do not type-check against the public API
  //   refine(sqrt(x**2), Q.real(x))
  //   => Abs(x)
  it.todo("refine(sqrt(x**2), Q.real(x))");
  // the arguments do not type-check against the public API
  //   refine(sqrt(x**2), Q.positive(x))
  //   => x
  it.todo("refine(sqrt(x**2), Q.positive(x))");
  it("refine(Q.real(x), Q.positive(x))", () => {
    const x = new Sym('x');
    expect(sympyStr(refine(Q.real(x), Q.positive(x)))).toBe('True');
  });
  it("refine(Q.positive(x), Q.real(x))", () => {
    const x = new Sym('x');
    expect(sympyStr(refine(Q.positive(x), Q.real(x)))).toBe('Q.positive(x)');
  });
  // the arguments do not type-check against the public API
  //   refine_Pow((-1)**x, Q.real(x))
  //   => None
  it.todo("refine_Pow((-1)**x, Q.real(x))");
  it("refine_Pow((-1)**x, Q.even(x))", () => {
    const x = new Sym('x');
    expect(sympyStr(refinePow(pow(-1, x), Q.even(x)))).toBe('1');
  });
  it("refine_Pow((-1)**x, Q.odd(x))", () => {
    const x = new Sym('x');
    expect(sympyStr(refinePow(pow(-1, x), Q.odd(x)))).toBe('-1');
  });
  it("refine_Pow((-1)**(x+y), Q.even(x))", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(refinePow(pow(-1, add(x, y)), Q.even(x)))).toBe('(-1)**y');
  });
  it("refine_Pow((-1)**(x+y+z), Q.odd(x) & Q.odd(z))", () => {
    const [x, y, z] = symbols('x y z');
    expect(sympyStr(refinePow(pow(-1, add(x, y, z)), And(Q.odd(x), Q.odd(z))))).toBe('(-1)**y');
  });
  it("refine_Pow((-1)**(x+y+2), Q.odd(x))", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(refinePow(pow(-1, add(2, x, y)), Q.odd(x)))).toBe('(-1)**(y + 1)');
  });
  it("refine_Pow((-1)**(x+3), True)", () => {
    const x = new Sym('x');
    expect(sympyStr(refinePow(pow(-1, add(3, x)), true))).toBe('(-1)**(x + 1)');
  });
  // the arguments do not type-check against the public API
  //   refine_abs(Abs(x), Q.real(x))
  //   => None
  it.todo("refine_abs(Abs(x), Q.real(x))");
  it("refine_abs(Abs(x), Q.positive(x))", () => {
    const x = new Sym('x');
    expect(sympyStr(refineAbs(abs(x), Q.positive(x)))).toBe('x');
  });
  it("refine_abs(Abs(x), Q.negative(x))", () => {
    const x = new Sym('x');
    expect(sympyStr(refineAbs(abs(x), Q.negative(x)))).toBe('-x');
  });
  it("refine_arg(arg(x), Q.positive(x))", () => {
    const x = new Sym('x');
    expect(sympyStr(refineArg(fn('arg', [x]), Q.positive(x)))).toBe('0');
  });
  it("refine_arg(arg(x), Q.negative(x))", () => {
    const x = new Sym('x');
    expect(sympyStr(refineArg(fn('arg', [x]), Q.negative(x)))).toBe('pi');
  });
  it("refine_atan2(atan2(y,x), Q.real(y) & Q.positive(x))", () => {
    const [y, x] = symbols('y x');
    expect(sympyStr(refineAtan2(fn('atan2', [y, x]), And(Q.positive(x), Q.real(y))))).toBe('atan(y/x)');
  });
  it("refine_atan2(atan2(y,x), Q.negative(y) & Q.negative(x))", () => {
    const [y, x] = symbols('y x');
    expect(sympyStr(refineAtan2(fn('atan2', [y, x]), And(Q.negative(x), Q.negative(y))))).toBe('atan(y/x) - pi');
  });
  it("refine_atan2(atan2(y,x), Q.positive(y) & Q.negative(x))", () => {
    const [y, x] = symbols('y x');
    expect(sympyStr(refineAtan2(fn('atan2', [y, x]), And(Q.negative(x), Q.positive(y))))).toBe('atan(y/x) + pi');
  });
  it("refine_atan2(atan2(y,x), Q.zero(y) & Q.negative(x))", () => {
    const [y, x] = symbols('y x');
    expect(sympyStr(refineAtan2(fn('atan2', [y, x]), And(Q.negative(x), Q.zero(y))))).toBe('pi');
  });
  it("refine_atan2(atan2(y,x), Q.positive(y) & Q.zero(x))", () => {
    const [y, x] = symbols('y x');
    expect(sympyStr(refineAtan2(fn('atan2', [y, x]), And(Q.positive(y), Q.zero(x))))).toBe('pi/2');
  });
  it("refine_atan2(atan2(y,x), Q.negative(y) & Q.zero(x))", () => {
    const [y, x] = symbols('y x');
    expect(sympyStr(refineAtan2(fn('atan2', [y, x]), And(Q.negative(y), Q.zero(x))))).toBe('-pi/2');
  });
  it("refine_atan2(atan2(y,x), Q.zero(y) & Q.zero(x))", () => {
    const [y, x] = symbols('y x');
    expect(sympyStr(refineAtan2(fn('atan2', [y, x]), And(Q.zero(x), Q.zero(y))))).toBe('nan');
  });
  it("refine_im(im(x), Q.real(x))", () => {
    const x = new Sym('x');
    expect(sympyStr(refineIm(fn('im', [x]), Q.real(x)))).toBe('0');
  });
  it("refine_im(im(x), Q.imaginary(x))", () => {
    const x = new Sym('x');
    expect(sympyStr(refineIm(fn('im', [x]), Q.imaginary(x)))).toBe('-I*x');
  });
  it("refine_matrixelement(X[0, 1], Q.symmetric(X))", () => {
    expect(sympyStr(refineMatrixelement(MatrixElement(new MatrixSymbol('X', rational(3), rational(3)), rational(0), rational(1)), Q.symmetric(new MatrixSymbol('X', rational(3), rational(3)))))).toBe('X[0, 1]');
  });
  it("refine_matrixelement(X[1, 0], Q.symmetric(X))", () => {
    expect(sympyStr(refineMatrixelement(MatrixElement(new MatrixSymbol('X', rational(3), rational(3)), rational(1), rational(0)), Q.symmetric(new MatrixSymbol('X', rational(3), rational(3)))))).toBe('X[0, 1]');
  });
  it("refine_re(re(x), Q.real(x))", () => {
    const x = new Sym('x');
    expect(sympyStr(refineRe(fn('re', [x]), Q.real(x)))).toBe('x');
  });
  it("refine_re(re(x), Q.imaginary(x))", () => {
    const x = new Sym('x');
    expect(sympyStr(refineRe(fn('re', [x]), Q.imaginary(x)))).toBe('0');
  });
  it("refine_sign(expr, Q.positive(x) & Q.nonzero(x))", () => {
    const x = new Sym('x', { real: true });
    expect(sympyStr(refineSign(fn('sign', [x]), And(Q.nonzero(x), Q.positive(x))))).toBe('1');
  });
  it("refine_sign(expr, Q.negative(x) & Q.nonzero(x))", () => {
    const x = new Sym('x', { real: true });
    expect(sympyStr(refineSign(fn('sign', [x]), And(Q.negative(x), Q.nonzero(x))))).toBe('-1');
  });
  it("refine_sign(expr, Q.zero(x))", () => {
    const x = new Sym('x', { real: true });
    expect(sympyStr(refineSign(fn('sign', [x]), Q.zero(x)))).toBe('0');
  });
  it("refine_sign(expr, Q.positive(im(y)))", () => {
    const y = new Sym('y', { imaginary: true });
    expect(sympyStr(refineSign(fn('sign', [y]), Q.positive(mul(-1, I, y))))).toBe('I');
  });
  it("refine_sign(expr, Q.negative(im(y)))", () => {
    const y = new Sym('y', { imaginary: true });
    expect(sympyStr(refineSign(fn('sign', [y]), Q.negative(mul(-1, I, y))))).toBe('-I');
  });
});

